def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    urgent_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0

    if not alive:
        return min(budget, 18)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0
    richest_opp = max(opp_budgets) if opp_budgets else 0

    units = supply / WATER_REQ
    tight = units < (len(alive) + 1)
    very_tight = units < len(alive)
    roomy = units >= (len(alive) + 1.5)

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1

    if danger >= 3:
        bid = max(92, highest_prev + 3)
    elif very_tight:
        bid = max(78, avg_prev + 2)
        if highest_prev > 0:
            bid = max(bid, highest_prev + 1.25)
    elif tight:
        bid = max(58, avg_prev * 0.78)
        if highest_prev >= 120:
            bid = max(52, highest_prev * 0.72)
    elif roomy:
        bid = 26 if hp > 5 else 40
    else:
        bid = 44

    if urgent_opp >= 2 and tight:
        bid += 8

    if richest_opp > budget * 2 and tight:
        bid += 6

    if day >= 8:
        if hp >= 6 and no_water_days == 0:
            bid *= 0.9
        else:
            bid *= 1.1

    if budget < 120:
        bid = min(bid, budget * 0.72)
    elif budget < 200:
        bid = min(bid, budget * 0.82)

    floor_bid = 12
    if danger >= 2:
        floor_bid = 45
    elif tight:
        floor_bid = 32

    bid = max(floor_bid, bid)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid a minimal amount to get water
    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid strategy:
    # Aggressive if critical, moderate otherwise.
    target_bid = DAILY_SALARY * 0.6 # Default moderate bid (90)

    if my_status['no_water_days'] > 0:
        target_bid = DAILY_SALARY * 0.95 # Very high if deprived (142.5)
    elif my_status['hp'] <= 2:
        target_bid = DAILY_SALARY * 0.9 # Critical HP (135)
    elif my_status['hp'] <= 4:
        target_bid = DAILY_SALARY * 0.75 # Low HP (112.5)

    current_bid = target_bid

    # Adjust bid based on opponent's previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        bid_to_beat = highest_prev_bid + 1.0 # Try to beat the highest bid

        if my_status['no_water_days'] > 0 or my_status['hp'] <= 4:
            # Critical condition: bid very aggressively, ensuring we try to beat it
            current_bid = max(target_bid, bid_to_beat)
            if bid_to_beat > DAILY_SALARY * 0.95: # If opponents are bidding almost max salary
                current_bid = max(current_bid, DAILY_SALARY * 0.98) # Bid even higher
        else:
            # Not critical: bid above previous, but with some budget consideration
            current_bid = max(target_bid, bid_to_beat)
            if highest_prev_bid >= DAILY_SALARY * 0.85: # Opponents are bidding very high (>= 127.5)
                # If healthy, cap bid to save budget, but still try to win
                current_bid = min(current_bid, DAILY_SALARY * 0.9) # Cap at 135 if healthy
                if my_status['hp'] > 6 and day_context['day'] < 8: # If very healthy and early days
                    current_bid = min(current_bid, DAILY_SALARY * 0.7) # Back off more (105)

    # Ensure bid is within budget and at least 1.0
    final_bid = min(my_status['budget'], current_bid)
    return max(1.0, final_bid)

